{
  "name": "Bimo机器人套件",
  "name_en": "Bimo Robotics Kit",
  "manufacturer": "",
  "description": "Bimo 是一套小型腿式机器人实验平台，配有舵机驱动关节、惯性测量单元、多个方向的测距传感器以及摄像头，并通过主控板进行通信控制。它适用于机器人教学与实验中的姿态估计、运动控制、关节校准、避障感知和视觉数据采集。",
  "description_en": "Bimo is a compact legged robotics platform with servo-actuated joints, an IMU, multi-direction distance sensors, and onboard cameras, controlled through an MCU. It is used in robotics teaching and laboratory work for posture estimation, motion control, joint calibration, obstacle sensing, and vision data acquisition.",
  "tag_hints": [
    "educational robotics",
    "legged robot",
    "servo actuation",
    "IMU sensing",
    "distance sensing",
    "robot vision",
    "motion control"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化机器人，并在需要时执行校准，使其回到坐姿起始状态。",
      "description_en": "Initialize the robot and optionally calibrate it, returning it to the sitting start posture."
    },
    {
      "action_name": "auto-calibrate",
      "description": "执行机器人踝部和舵机的交互式校准。",
      "description_en": "Perform interactive calibration of the robot's ankles and servos."
    },
    {
      "action_name": "auto-update_imu_offsets",
      "description": "更新惯性测量单元的偏置参数。",
      "description_en": "Update the offset parameters of the inertial measurement unit."
    },
    {
      "action_name": "auto-init_mcu_comms",
      "description": "建立与机器人主控单元的通信连接。",
      "description_en": "Establish communication with the robot's MCU."
    },
    {
      "action_name": "auto-request_state_data",
      "description": "读取机器人状态数据，包括姿态、测距、舵机位置和速度。",
      "description_en": "Read robot state data, including orientation, distance measurements, servo positions, and servo speeds."
    },
    {
      "action_name": "auto-send_positions",
      "description": "向机器人舵机发送目标关节角度动作。",
      "description_en": "Send target joint-angle commands to the robot servos."
    },
    {
      "action_name": "auto-calibrate_servos",
      "description": "对机器人舵机执行校准。",
      "description_en": "Calibrate the robot servos."
    },
    {
      "action_name": "auto-available",
      "description": "检查机器人主控是否就绪可用。",
      "description_en": "Check whether the robot MCU is ready for use."
    },
    {
      "action_name": "auto-port",
      "description": "获取机器人主控的通信端口信息。",
      "description_en": "Get the communication port information for the robot MCU."
    },
    {
      "action_name": "auto-init_cameras",
      "description": "初始化机器人摄像头。",
      "description_en": "Initialize the robot cameras."
    },
    {
      "action_name": "auto-capture_image",
      "description": "从机器人摄像头采集单帧图像。",
      "description_en": "Capture a single image frame from a robot camera."
    },
    {
      "action_name": "auto-scale_value",
      "description": "按给定范围对控制量或传感值进行缩放。",
      "description_en": "Scale control values or sensor values according to a given range."
    },
    {
      "action_name": "auto-clip_actions",
      "description": "将机器人关节动作角度限制在允许范围内。",
      "description_en": "Limit robot joint action angles to the allowed range."
    },
    {
      "action_name": "auto-quaternion_to_euler",
      "description": "将机器人姿态四元数转换为欧拉角。",
      "description_en": "Convert the robot orientation from quaternion form to Euler angles."
    },
    {
      "action_name": "auto-servo2deg",
      "description": "将舵机读数换算为关节角度。",
      "description_en": "Convert servo readings into joint angles."
    },
    {
      "action_name": "auto-deg2servo",
      "description": "将目标关节角度换算为舵机位置值。",
      "description_en": "Convert target joint angles into servo position values."
    }
  ]
}

